async function pause(ms: number): Promise<void> {
  try {
    await sleep(ms, undefined, { signal: stop.signal });
  } catch {
    // aborted by shutdown
  }
}

/** Runs one attempt of a claimed job. Returns early, leaving the job `running`, if shutdown is requested. */
async function runAttempt(job: JobRow, attempt: number): Promise<void> {
  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: fails at the first step, before any progress.
    await pause(STEP_MS);
    if (stopping) return;
    if (attempt < MAX_ATTEMPTS) requeue.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    else fail.run(nowIso(), job.id);
    return;
  }
  for (let completed = 1; completed <= job.steps; completed++) {
    await pause(STEP_MS);
    if (stopping) return;
    setProgress.run(completed, nowIso(), job.id);
  }
  complete.run(job.input.toUpperCase(), nowIso(), job.id);
}

function heartbeat(): void {
  try {
    beat.run(Date.now());
  } catch (e) {
    console.error('heartbeat failed:', e instanceof Error ? e.message : String(e));
  }
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
    stop.abort();
  });
}

// A job left `running` by a previous worker that died is processed again from the start.
recoverRunning.run(nowIso());
heartbeat();
const heartbeatTimer = setInterval(heartbeat, HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    const job = nextQueued.get(Date.now()) as JobRow | undefined;
    if (!job) {
      await pause(POLL_MS);
      continue;
    }
    const claimed = claim.get(nowIso(), job.id) as { attempts: number } | undefined;
    if (!claimed) continue;
    await runAttempt(job, claimed.attempts);
  } catch (e) {
    console.error('worker error:', e instanceof Error ? e.stack ?? e.message : String(e));
    await pause(1000);
  }
}

clearInterval(heartbeatTimer);
// A stopped worker reports "down" immediately rather than after the 3-second staleness window.
db.prepare('UPDATE worker_heartbeat SET beat_at = 0 WHERE id = 1').run();
db.close();
console.log('worker stopped');
process.exit(0);
